INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-account-opening-individual-fr', 'account_opening_individual', 'account_opening', 'fr', 'Ouvrir un compte personnel', 'Pour ouvrir un compte courant ou d''épargne personnel, présentez-vous dans n''importe quelle agence avec : votre carte nationale d''identité (CNI) ou votre passeport en cours de validité, deux photos d''identité récentes et une attestation de résidence délivrée par votre commune. Le dépôt minimum à l''ouverture est de 10 000 FBu pour un compte courant et de 5 000 FBu pour un compte d''épargne. Le compte est ouvert le jour même et la carte de débit est prête en 5 jours ouvrables. Les mineurs ouvrent un compte avec un parent ou tuteur qui présente sa propre CNI et l''acte de naissance de l''enfant.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-account-opening-individual-en', 'account_opening_individual', 'account_opening', 'en', 'Opening a personal account', 'To open a personal current or savings account, visit any branch with: your valid national ID card (CNI) or passport, two recent passport photos and a certificate of residence from your commune. The minimum opening deposit is 10,000 FBu for a current account and 5,000 FBu for a savings account. The account is opened the same day and the debit card is ready in 5 working days. Minors open an account with a parent or guardian, who brings their own ID and the child''s birth certificate.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-account-opening-individual-rn', 'account_opening_individual', 'account_opening', 'rn', 'Kwugurura konti y''umuntu ku giti ciwe', 'Kugira mwugurure konti isanzwe canke konti yo kuzigama, nimuze ku ishami iryo ari ryo ryose muzanye: ikarata karangamuntu (CNI) canke pasiporo itararenza igihe, amafoto abiri mashasha n''icemezo c''aho muba gitangwa na komine. Amafaranga make yo gutangura ni 10 000 FBu kuri konti isanzwe na 5 000 FBu kuri konti yo kuzigama. Konti yugururwa uwo musi nyene, ikarata ikaboneka mu misi 5 y''akazi. Abana bato bugururirwa konti n''umuvyeyi canke uwubarera, azana karangamuntu yiwe n''icemezo c''amavuka c''umwana.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-account-opening-business-fr', 'account_opening_business', 'account_opening', 'fr', 'Ouvrir un compte entreprise ou association', 'Pour un compte d''entreprise, apportez : le registre de commerce, le numéro d''identification fiscale (NIF), les statuts de la société, la CNI de chaque signataire et le procès-verbal désignant les signataires. Pour une association ou une coopérative, apportez l''agrément, les statuts et la liste des membres du comité. Le dépôt minimum est de 50 000 FBu. L''ouverture prend 2 jours ouvrables après réception du dossier complet.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-account-opening-business-en', 'account_opening_business', 'account_opening', 'en', 'Opening a business or association account', 'For a business account, bring: the trade register certificate, the tax identification number (NIF), the company statutes, the national ID of each signatory and the minutes naming the signatories. For an association or cooperative, bring the official approval, the statutes and the list of committee members. The minimum deposit is 50,000 FBu. Opening takes 2 working days after the full file is received.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-account-opening-business-rn', 'account_opening_business', 'account_opening', 'rn', 'Kwugurura konti y''ishirahamwe canke y''umugwi', 'Ku konti y''ishirahamwe ry''ubudandaji, muzane: icemezo c''iyandikwa mu bucuruzi, inomero y''umusoro (NIF), amategeko ngenderwako y''ishirahamwe, karangamuntu y''umuntu wese azosinya n''inyandiko ishinga abazosinya. Ku mugwi canke koperative, muzane uruhusha, amategeko ngenderwako n''urutonde rw''abagize komite. Amafaranga make yo gutangura ni 50 000 FBu. Konti yugururwa mu misi 2 y''akazi inyuma yo kwakira impapuro zose.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-account-types-fr', 'account_types', 'product_info', 'fr', 'Nos comptes', 'Compte courant : pour les opérations de tous les jours, carte de débit incluse, frais de tenue de compte de 2 000 FBu par mois. Compte d''épargne : intérêt de 3 % par an, sans frais de tenue, deux retraits gratuits par mois. Compte jeune (moins de 25 ans) : sans frais de tenue de compte, carte de débit gratuite la première année. Tous les comptes donnent accès à la banque mobile et au service *123#.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-account-types-en', 'account_types', 'product_info', 'en', 'Our accounts', 'Current account: for everyday banking, debit card included, maintenance fee of 2,000 FBu per month. Savings account: 3% interest per year, no maintenance fee, two free withdrawals per month. Youth account (under 25): no maintenance fee, free debit card for the first year. All accounts include mobile banking and the *123# service.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-account-types-rn', 'account_types', 'product_info', 'rn', 'Konti zacu', 'Konti isanzwe: ni iyo gukoresha buri musi, irimwo ikarata, amafaranga yo kuyibungabunga ni 2 000 FBu ku kwezi. Konti yo kuzigama: inyungu ya 3 % ku mwaka, nta mafaranga yo kuyibungabunga, mushobora gukura amafaranga kabiri ku kwezi ata co murihiye. Konti y''urwaruka (munsi y''imyaka 25): nta mafaranga yo kuyibungabunga, ikarata ni ubuntu mu mwaka wa mbere. Konti zose zirashobora gukoreshwa kuri terefone no kuri *123#.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-debit-cards-fr', 'debit_cards', 'product_info', 'fr', 'Cartes de débit', 'Nous proposons une carte Visa débit, utilisable au Burundi et à l''étranger, et une carte de débit locale, utilisable dans nos guichets automatiques et chez les commerçants partenaires au Burundi. Frais d''émission : 10 000 FBu. Cotisation annuelle : 12 000 FBu pour la Visa, 6 000 FBu pour la carte locale. Retrait gratuit à nos guichets automatiques, 1 000 FBu dans ceux d''autres banques. Plafond de retrait : 1 000 000 FBu par jour.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-debit-cards-en', 'debit_cards', 'product_info', 'en', 'Debit cards', 'We offer a Visa debit card, usable in Burundi and abroad, and a local debit card, usable at our ATMs and at partner merchants in Burundi. Issuing fee: 10,000 FBu. Annual fee: 12,000 FBu for Visa, 6,000 FBu for the local card. Withdrawals are free at our ATMs and cost 1,000 FBu at other banks'' ATMs. Withdrawal limit: 1,000,000 FBu per day.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-debit-cards-rn', 'debit_cards', 'product_info', 'rn', 'Amakarata yo kubikuza', 'Dufise ikarata Visa ikoreshwa mu Burundi no hanze y''igihugu, n''ikarata y''imbere mu gihugu ikoreshwa ku byuma vyacu vya ATM no ku badandaji dukorana mu Burundi. Amafaranga yo kuyironka: 10 000 FBu. Amafaranga y''umwaka: 12 000 FBu kuri Visa, 6 000 FBu ku karata y''imbere mu gihugu. Gukura amafaranga ku byuma vyacu ni ubuntu, ku vy''izindi banki ni 1 000 FBu. Ntimushobora gukura arenga 1 000 000 FBu ku musi.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-card-lost-stolen-fr', 'card_lost_stolen', 'card_block', 'fr', 'Carte perdue ou volée', 'Si votre carte est perdue ou volée, faites-la bloquer immédiatement : par ce service d''appel, par le menu *123# (option 2) ou dans une agence. Pour bloquer la carte, nous vérifions votre identité avec votre numéro de compte et votre code PIN ou votre date de naissance. Vous recevez un numéro de référence de blocage. Le blocage est définitif : pour une nouvelle carte, passez en agence avec votre CNI. Le remplacement coûte 10 000 FBu et la carte est prête en 5 jours ouvrables. Ne communiquez jamais votre code PIN par SMS ou WhatsApp.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-card-lost-stolen-en', 'card_lost_stolen', 'card_block', 'en', 'Lost or stolen card', 'If your card is lost or stolen, have it blocked immediately: through this call service, through the *123# menu (option 2) or at a branch. To block the card we check your identity with your account number and your PIN or date of birth. You receive a block reference number. Blocking is permanent: for a new card, visit a branch with your national ID. Replacement costs 10,000 FBu and the card is ready in 5 working days. Never send your PIN by SMS or WhatsApp.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-card-lost-stolen-rn', 'card_lost_stolen', 'card_block', 'rn', 'Ikarata yatakaye canke yibwe', 'Ikarata yanyu niyatakara canke ikibwa, nimuyihagarike ubwo nyene: muciye kuri iyi serivisi, kuri *123# (ihitamwo rya 2) canke ku ishami. Kugira duhagarike ikarata, turabanza kwemeza ko ari mwebwe dukoresheje inomero ya konti n''inomero y''ibanga (PIN) canke itariki y''amavuka. Murahabwa inomero y''icemezo c''ihagarikwa. Ikarata ihagaritswe ntisubira gukora: kugira muronke iyindi, nimuze ku ishami muzanye karangamuntu. Iyindi karata ni 10 000 FBu, ikaboneka mu misi 5 y''akazi. Ntimukigere murungika inomero y''ibanga kuri SMS canke WhatsApp.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-card-blocked-pin-fr', 'card_blocked_pin', 'card_block', 'fr', 'Carte bloquée après des codes PIN erronés', 'Après 3 codes PIN erronés, la carte se bloque automatiquement pour votre sécurité. Pour la débloquer, passez dans une agence avec votre CNI et votre carte : le déblocage est gratuit et se fait dans les 24 heures. Si vous avez oublié votre code PIN, l''agence vous remet un nouveau code sous pli fermé contre 2 000 FBu. Si la carte a été avalée par un guichet automatique, voir l''article sur les cartes avalées.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-card-blocked-pin-en', 'card_blocked_pin', 'card_block', 'en', 'Card blocked after wrong PIN entries', 'After 3 wrong PIN entries the card blocks automatically for your safety. To unblock it, visit a branch with your national ID and your card: unblocking is free and done within 24 hours. If you forgot your PIN, the branch gives you a new PIN in a sealed envelope for 2,000 FBu. If an ATM kept the card, see the article on swallowed cards.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-card-blocked-pin-rn', 'card_blocked_pin', 'card_block', 'rn', 'Ikarata yahagaze kubera inomero y''ibanga itari yo', 'Iyo mwinjije inomero y''ibanga itari yo incuro 3, ikarata ica ihagarara ubwayo kugira ngo mukingirwe. Kugira yongere ikore, nimuze ku ishami muzanye karangamuntu n''ikarata: ni ubuntu, bikorwa mu masaha 24. Nimwaba mwibagiye inomero y''ibanga, ishami rirabaha iyindi mu ibahasha ifunze ku 2 000 FBu. Nimba icuma ca ATM camize ikarata, raba ingingo ivuga ku makarata yamizwe.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-card-swallowed-atm-fr', 'card_swallowed_atm', 'card_block', 'fr', 'Carte avalée par un guichet automatique', 'Si un de nos guichets automatiques a gardé votre carte, elle est remise à l''agence la plus proche du guichet dans un délai de 2 jours ouvrables. Retirez-la en agence avec votre CNI ; c''est gratuit. Si c''est le guichet d''une autre banque, le délai est de 7 jours ouvrables. Si vous pensez que la carte a été volée au guichet, demandez son blocage immédiat.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-card-swallowed-atm-en', 'card_swallowed_atm', 'card_block', 'en', 'Card swallowed by an ATM', 'If one of our ATMs kept your card, it is sent to the branch nearest that ATM within 2 working days. Collect it at the branch with your national ID; this is free. If it was another bank''s ATM, it takes 7 working days. If you think the card was stolen at the ATM, ask for it to be blocked immediately.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-card-swallowed-atm-rn', 'card_swallowed_atm', 'card_block', 'rn', 'Ikarata yamizwe n''icuma ca ATM', 'Nimba icuma cacu ca ATM cagumanye ikarata yanyu, irashikirizwa ishami riri hafi y''ico cuma mu misi 2 y''akazi. Muyitora ku ishami muzanye karangamuntu; ni ubuntu. Nimba ari icuma c''iyindi banki, bifata imisi 7 y''akazi. Nimwiyumvira ko ikarata yibiwe kuri ATM, nimusabe ko ihagarikwa ubwo nyene.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-mobile-banking-fr', 'mobile_banking', 'product_info', 'fr', 'Banque mobile et *123#', 'Avec l''application mobile ou le menu *123# (fonctionne sur tous les téléphones, sans internet), vous pouvez consulter votre solde, voir vos 5 dernières opérations, bloquer votre carte, poser une question et déposer une réclamation. L''inscription est gratuite en agence ou par ce service d''appel. Chaque consultation de solde par *123# coûte 100 FBu.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-mobile-banking-en', 'mobile_banking', 'product_info', 'en', 'Mobile banking and *123#', 'With the mobile app or the *123# menu (works on every phone, no internet needed), you can check your balance, see your last 5 transactions, block your card, ask a question and file a complaint. Registration is free at a branch or through this call service. Each balance check by *123# costs 100 FBu.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-mobile-banking-rn', 'mobile_banking', 'product_info', 'rn', 'Banki kuri terefone na *123#', 'Mukoresheje porogarama ya terefone canke *123# (ikora kuri terefone zose, nta internet ikenewe), murashobora kuraba amafaranga ari kuri konti, kuraba ibikorwa 5 biheruka, guhagarika ikarata, kubaza ikibazo no gutanga ikirego. Kwiyandikisha ni ubuntu ku ishami canke kuri iyi serivisi. Kuraba amafaranga kuri *123# ni 100 FBu incuro imwe.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-fees-schedule-fr', 'fees_schedule', 'product_info', 'fr', 'Principaux frais', 'Tenue de compte courant : 2 000 FBu par mois. Compte d''épargne et compte jeune : sans frais de tenue. Émission de carte : 10 000 FBu ; remplacement : 10 000 FBu. Cotisation annuelle carte Visa : 12 000 FBu ; carte locale : 6 000 FBu. Retrait au guichet automatique d''une autre banque : 1 000 FBu. Nouveau code PIN : 2 000 FBu. Relevé de compte imprimé : 1 500 FBu. Consultation de solde par *123# : 100 FBu. Frais de dossier de crédit : 1 % du montant, minimum 5 000 FBu.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-fees-schedule-en', 'fees_schedule', 'product_info', 'en', 'Main fees', 'Current account maintenance: 2,000 FBu per month. Savings and youth accounts: no maintenance fee. Card issuing: 10,000 FBu; replacement: 10,000 FBu. Annual card fee: Visa 12,000 FBu, local card 6,000 FBu. Withdrawal at another bank''s ATM: 1,000 FBu. New PIN: 2,000 FBu. Printed statement: 1,500 FBu. Balance check by *123#: 100 FBu. Loan processing fee: 1% of the amount, minimum 5,000 FBu.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-fees-schedule-rn', 'fees_schedule', 'product_info', 'rn', 'Amafaranga nyamukuru y''ibikorwa', 'Kubungabunga konti isanzwe: 2 000 FBu ku kwezi. Konti yo kuzigama na konti y''urwaruka: nta mafaranga yo kuzibungabunga. Kuronka ikarata: 10 000 FBu; kuyisubiza: 10 000 FBu. Amafaranga y''umwaka y''ikarata: Visa 12 000 FBu, ikarata y''imbere mu gihugu 6 000 FBu. Gukura amafaranga ku cuma c''iyindi banki: 1 000 FBu. Inomero y''ibanga nshasha: 2 000 FBu. Urupapuro rw''ibikorwa vya konti: 1 500 FBu. Kuraba amafaranga kuri *123#: 100 FBu. Amafaranga y''idosiye y''ingurane: 1 % y''ayo musaba, ntarengwa 5 000 FBu nk''amake.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-loans-overview-fr', 'loans_overview', 'loan_info', 'fr', 'Nos crédits en bref', 'Nous proposons six crédits : crédit commerce, crédit agricole, avance sur salaire, crédit habitat, crédit scolaire et crédit groupe solidaire de femmes. Conditions communes : avoir un compte chez nous, présenter sa CNI, prouver des revenus réguliers et payer les frais de dossier (1 % du montant, minimum 5 000 FBu). La réponse est donnée en 5 jours ouvrables après réception du dossier complet. Ce service peut calculer votre mensualité à partir du montant et de la durée.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-loans-overview-en', 'loans_overview', 'loan_info', 'en', 'Our loans at a glance', 'We offer six loans: business loan, agricultural loan, salary advance, housing loan, school fees loan and women''s solidarity group loan. Common conditions: hold an account with us, show your national ID, prove regular income and pay the processing fee (1% of the amount, minimum 5,000 FBu). You get an answer within 5 working days after the full file is received. This service can calculate your monthly payment from the amount and the term.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-loans-overview-rn', 'loans_overview', 'loan_info', 'rn', 'Ingurane zacu muri make', 'Dufise ingurane zitandatu: ingurane y''ubudandaji, ingurane y''uburimyi, ingurane y''umushahara, ingurane yo kwubaka inzu, ingurane y''amashure n''ingurane y''imigwi y''abagore. Ivyo zose zisaba: kuba mufise konti iwacu, kwerekana karangamuntu, kwerekana ko mufise amafaranga yinjira buri gihe no kuriha amafaranga y''idosiye (1 % y''ayo musaba, ntarengwa 5 000 FBu). Inyishu itangwa mu misi 5 y''akazi inyuma yo kwakira impapuro zose. Iyi serivisi irashobora kubaharurira ivyo muzoriha buri kwezi mukurikije amafaranga n''igihe.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-complaint-process-fr', 'complaint_process', 'complaint', 'fr', 'Déposer une réclamation', 'Vous pouvez déposer une réclamation par ce service d''appel, par *123# (option 4), par WhatsApp ou en agence. Chaque réclamation reçoit un numéro de ticket (par exemple TCK-2026-00042) à conserver. Nous confirmons la réception dans les 24 heures et visons une réponse en 5 jours ouvrables. Si des frais ont été prélevés par erreur, ils sont remboursés dans les 5 jours ouvrables après vérification. Une réclamation urgente (fraude, argent manquant) est transmise immédiatement à un conseiller.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-complaint-process-en', 'complaint_process', 'complaint', 'en', 'Filing a complaint', 'You can file a complaint through this call service, through *123# (option 4), on WhatsApp or at a branch. Each complaint gets a ticket number (for example TCK-2026-00042); keep it. We confirm receipt within 24 hours and aim to answer within 5 working days. Fees charged by mistake are refunded within 5 working days after verification. An urgent complaint (fraud, missing money) is passed to an agent immediately.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-complaint-process-rn', 'complaint_process', 'complaint', 'rn', 'Gutanga ikirego', 'Murashobora gutanga ikirego muciye kuri iyi serivisi, kuri *123# (ihitamwo rya 4), kuri WhatsApp canke ku ishami. Ikirego cose gihabwa inomero y''itike (nk''akarorero TCK-2026-00042); muyibike. Turemeza ko twakiriye ikirego mu masaha 24, tukagerageza kwishura mu misi 5 y''akazi. Amafaranga yakuweko ku makosa asubizwa mu misi 5 y''akazi inyuma yo kugenzura. Ikirego cihutirwa (ubusuma, amafaranga yabuze) gishikirizwa umukozi ubwo nyene.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-branch-hours-general-fr', 'branch_hours_general', 'branch_info', 'fr', 'Horaires des agences et du service client', 'La plupart des agences sont ouvertes du lundi au vendredi de 8 h à 17 h et le samedi de 8 h à 12 h ; elles sont fermées le dimanche et les jours fériés. Les horaires exacts de chaque agence sont donnés par province ou par ville. L''assistant Kabangutsi répond 24 h sur 24. Les conseillers humains répondent du lundi au vendredi de 7 h 30 à 18 h et le samedi de 8 h à 12 h.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-branch-hours-general-en', 'branch_hours_general', 'branch_info', 'en', 'Branch and customer service hours', 'Most branches are open Monday to Friday from 8:00 to 17:00 and Saturday from 8:00 to 12:00; they are closed on Sundays and public holidays. Exact hours for each branch are given by province or town. The Kabangutsi assistant answers 24 hours a day. Human agents answer Monday to Friday from 7:30 to 18:00 and Saturday from 8:00 to 12:00.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-branch-hours-general-rn', 'branch_hours_general', 'branch_info', 'rn', 'Amasaha y''amashami n''aya serivisi y''abakiriya', 'Amashami menshi akora kuva ku wa mbere gushika ku wa gatanu kuva 8:00 gushika 17:00, no ku wa gatandatu kuva 8:00 gushika 12:00; ntakora ku w''iyinga no ku misi mikuru. Amasaha nyayo ya buri shami atangwa hakurikijwe intara canke igisagara. Umufasha Kabangutsi yishura amasaha 24 kuri 24. Abakozi bishura kuva ku wa mbere gushika ku wa gatanu kuva 7:30 gushika 18:00, no ku wa gatandatu kuva 8:00 gushika 12:00.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-talk-to-agent-fr', 'talk_to_agent', 'handoff', 'fr', 'Parler à un conseiller', 'Dites « je veux parler à un conseiller » à tout moment, ou tapez 0 dans le menu *123#. Votre appel est transféré avec un résumé de la conversation, vous n''avez donc pas à tout répéter. En dehors des heures des conseillers, une réclamation est créée et un conseiller vous rappelle le jour ouvrable suivant.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-talk-to-agent-en', 'talk_to_agent', 'handoff', 'en', 'Talking to an agent', 'Say "I want to talk to an agent" at any time, or press 0 in the *123# menu. Your call is transferred with a summary of the conversation, so you don''t have to repeat everything. Outside agent hours, a ticket is created and an agent calls you back on the next working day.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-talk-to-agent-rn', 'talk_to_agent', 'handoff', 'rn', 'Kuvugana n''umukozi', 'Igihe ico ari co cose, muvuge ngo « ndashaka kuvugana n''umukozi », canke mukande 0 kuri *123#. Umuhamagaro wanyu urashikirizwa umukozi hamwe n''incamake y''ico mwavuganye, ku buryo mutasubiramwo vyose. Inyuma y''amasaha y''abakozi, ikirego kirandikwa, umukozi akabahamagara ku musi w''akazi ukurikira.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-security-tips-fr', 'security_tips', 'product_info', 'fr', 'Conseils de sécurité', 'La banque ne vous demandera jamais votre code PIN par SMS, WhatsApp ou e-mail. Saisissez votre code uniquement sur un guichet automatique, un terminal de paiement ou lors de la vérification d''identité de ce service d''appel. Ne prêtez jamais votre carte. En cas de doute sur un message ou un appel, bloquez votre carte et contactez une agence.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-security-tips-en', 'security_tips', 'product_info', 'en', 'Security tips', 'The bank will never ask for your PIN by SMS, WhatsApp or email. Enter your PIN only at an ATM, a payment terminal or during the identity check of this call service. Never lend your card. If a message or a call looks suspicious, block your card and contact a branch.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-security-tips-rn', 'security_tips', 'product_info', 'rn', 'Inama z''umutekano', 'Banki ntizigera ibasaba inomero y''ibanga kuri SMS, WhatsApp canke imeyili. Inomero y''ibanga muyinjiza gusa ku cuma ca ATM, ku cuma co kurihirako canke igihe iyi serivisi ibemeza. Ntimukigere mutiza abandi ikarata yanyu. Nimwakeka ubutumwa canke umuhamagaro, nimuhagarike ikarata mubaze ishami.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-loan-business-loan-fr', 'loan_business_loan', 'loan_info', 'fr', 'Crédit commerce', 'Crédit commerce : Pour financer le stock, l''équipement ou le fonds de roulement d''un commerce. Taux : 16 % par an. Montant : de 500 000 FBu à 50 000 000 FBu. Durée : de 3 à 36 mois. Conditions : Compte courant chez nous depuis au moins 6 mois; Registre de commerce et NIF; Relevés de compte des 6 derniers mois; Garantie (matériel, stock ou caution) au-delà de 10 000 000 FBu. Frais de dossier : 1 % du montant, minimum 5 000 FBu.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-loan-business-loan-en', 'loan_business_loan', 'loan_info', 'en', 'Business loan', 'Business loan: To finance stock, equipment or working capital for a business. Rate: 16% per year. Amount: from 500,000 FBu to 50,000,000 FBu. Term: from 3 to 36 months. Requirements: Current account with us for at least 6 months; Trade register certificate and NIF; Account statements for the last 6 months; Collateral (equipment, stock or guarantor) above 10,000,000 FBu. Processing fee: 1% of the amount, minimum 5,000 FBu.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-loan-business-loan-rn', 'loan_business_loan', 'loan_info', 'rn', 'Ingurane y''ubudandaji', 'Ingurane y''ubudandaji: Ifasha kugura ibidandazwa, ibikoresho canke amafaranga yo gukoresha mu budandaji. Inyungu: 16 % ku mwaka. Amafaranga: kuva kuri 500 000 FBu gushika kuri 50 000 000 FBu. Igihe: kuva ku mezi 3 gushika ku mezi 36. Ivyo bisaba: Konti isanzwe iwacu imaze nibura amezi 6; Icemezo c''iyandikwa mu bucuruzi na NIF; Impapuro z''ibikorwa vya konti z''amezi 6 aheruka; Ingwati (ibikoresho, ibidandazwa canke umwishingizi) iyo ingurane irenze 10 000 000 FBu. Amafaranga y''idosiye: 1 % y''ayo musaba, ntarengwa 5 000 FBu.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-loan-agri-loan-fr', 'loan_agri_loan', 'loan_info', 'fr', 'Crédit agricole', 'Crédit agricole : Pour les producteurs de café, de thé et de cultures vivrières : intrants, main-d''œuvre, petit matériel. Remboursement possible en une fois après la récolte. Taux : 12 % par an. Montant : de 100 000 FBu à 10 000 000 FBu. Durée : de 3 à 18 mois. Conditions : Compte chez nous; Attestation de la coopérative ou de la station de lavage; Reçus de livraison de la dernière récolte. Frais de dossier : 1 % du montant, minimum 5 000 FBu.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-loan-agri-loan-en', 'loan_agri_loan', 'loan_info', 'en', 'Agricultural loan', 'Agricultural loan: For coffee, tea and food crop farmers: inputs, labour, small equipment. Can be repaid in one payment after the harvest. Rate: 12% per year. Amount: from 100,000 FBu to 10,000,000 FBu. Term: from 3 to 18 months. Requirements: Account with us; Certificate from the cooperative or washing station; Delivery receipts from the last harvest. Processing fee: 1% of the amount, minimum 5,000 FBu.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-loan-agri-loan-rn', 'loan_agri_loan', 'loan_info', 'rn', 'Ingurane y''uburimyi', 'Ingurane y''uburimyi: Ku barimyi b''ikawa, icayi n''ibifungurwa: ifumbire, imbuto, abakozi, ibikoresho bito. Irashobora kurihwa rimwe inyuma y''isarura. Inyungu: 12 % ku mwaka. Amafaranga: kuva kuri 100 000 FBu gushika kuri 10 000 000 FBu. Igihe: kuva ku mezi 3 gushika ku mezi 18. Ivyo bisaba: Konti iwacu; Icemezo ca koperative canke c''aho bogereza ikawa; Ivyemezo vyo gutanga umwimbu uheruka. Amafaranga y''idosiye: 1 % y''ayo musaba, ntarengwa 5 000 FBu.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-loan-salary-advance-fr', 'loan_salary_advance', 'loan_info', 'fr', 'Avance sur salaire', 'Avance sur salaire : Pour les salariés dont le salaire est versé chez nous : jusqu''à 50 % du salaire net mensuel par mois de remboursement. Taux : 14 % par an. Montant : de 50 000 FBu à 5 000 000 FBu. Durée : de 1 à 24 mois. Conditions : Salaire domicilié chez nous depuis 3 mois; Attestation de service de l''employeur; Trois derniers bulletins de paie. Frais de dossier : 1 % du montant, minimum 5 000 FBu.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-loan-salary-advance-en', 'loan_salary_advance', 'loan_info', 'en', 'Salary advance', 'Salary advance: For employees whose salary is paid into an account with us: monthly repayments of up to 50% of net monthly salary. Rate: 14% per year. Amount: from 50,000 FBu to 5,000,000 FBu. Term: from 1 to 24 months. Requirements: Salary paid into an account with us for 3 months; Employment certificate from the employer; Last three payslips. Processing fee: 1% of the amount, minimum 5,000 FBu.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-loan-salary-advance-rn', 'loan_salary_advance', 'loan_info', 'rn', 'Ingurane y''umushahara', 'Ingurane y''umushahara: Ku bakozi bahemberwa kuri konti iwacu: ico muriha buri kwezi ntigishobora kurenza 50 % y''umushahara. Inyungu: 14 % ku mwaka. Amafaranga: kuva kuri 50 000 FBu gushika kuri 5 000 000 FBu. Igihe: kuva ku mezi 1 gushika ku mezi 24. Ivyo bisaba: Umushahara uca iwacu mu mezi 3 aheruka; Icemezo c''akazi gitangwa n''umukoresha; Impapuro z''umushahara z''amezi 3 aheruka. Amafaranga y''idosiye: 1 % y''ayo musaba, ntarengwa 5 000 FBu.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-loan-housing-loan-fr', 'loan_housing_loan', 'loan_info', 'fr', 'Crédit habitat', 'Crédit habitat : Pour construire, acheter ou rénover un logement. Taux : 15 % par an. Montant : de 5 000 000 FBu à 150 000 000 FBu. Durée : de 12 à 180 mois. Conditions : Revenus réguliers prouvés; Titre de propriété ou certificat d''enregistrement de la parcelle; Devis ou plan de construction; Apport personnel d''au moins 20 %. Frais de dossier : 1 % du montant, minimum 5 000 FBu.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-loan-housing-loan-en', 'loan_housing_loan', 'loan_info', 'en', 'Housing loan', 'Housing loan: To build, buy or renovate a home. Rate: 15% per year. Amount: from 5,000,000 FBu to 150,000,000 FBu. Term: from 12 to 180 months. Requirements: Proof of regular income; Land title or plot registration certificate; Construction quote or plan; Own contribution of at least 20%. Processing fee: 1% of the amount, minimum 5,000 FBu.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-loan-housing-loan-rn', 'loan_housing_loan', 'loan_info', 'rn', 'Ingurane yo kwubaka', 'Ingurane yo kwubaka: Ifasha kwubaka, kugura canke gusubiramwo inzu. Inyungu: 15 % ku mwaka. Amafaranga: kuva kuri 5 000 000 FBu gushika kuri 150 000 000 FBu. Igihe: kuva ku mezi 12 gushika ku mezi 180. Ivyo bisaba: Kwerekana amafaranga yinjira buri gihe; Icemezo c''itongo; Igiciro canke igishushanyo c''inzu; Gutanga nibura 20 % y''amafaranga yose. Amafaranga y''idosiye: 1 % y''ayo musaba, ntarengwa 5 000 FBu.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-loan-school-fees-loan-fr', 'loan_school_fees_loan', 'loan_info', 'fr', 'Crédit scolaire', 'Crédit scolaire : Pour payer les frais scolaires et universitaires au début de l''année ou du trimestre. Taux : 13 % par an. Montant : de 100 000 FBu à 3 000 000 FBu. Durée : de 3 à 10 mois. Conditions : Compte chez nous; Facture ou attestation d''inscription de l''école; Preuve de revenus. Frais de dossier : 1 % du montant, minimum 5 000 FBu.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-loan-school-fees-loan-en', 'loan_school_fees_loan', 'loan_info', 'en', 'School fees loan', 'School fees loan: To pay school or university fees at the start of the year or term. Rate: 13% per year. Amount: from 100,000 FBu to 3,000,000 FBu. Term: from 3 to 10 months. Requirements: Account with us; School invoice or enrolment certificate; Proof of income. Processing fee: 1% of the amount, minimum 5,000 FBu.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-loan-school-fees-loan-rn', 'loan_school_fees_loan', 'loan_info', 'rn', 'Ingurane y''amashure', 'Ingurane y''amashure: Ifasha kuriha amafaranga y''ishure canke kaminuza mu ntango y''umwaka canke y''igihembwe. Inyungu: 13 % ku mwaka. Amafaranga: kuva kuri 100 000 FBu gushika kuri 3 000 000 FBu. Igihe: kuva ku mezi 3 gushika ku mezi 10. Ivyo bisaba: Konti iwacu; Inyemezamafaranga canke icemezo c''ishure; Kwerekana amafaranga yinjira. Amafaranga y''idosiye: 1 % y''ayo musaba, ntarengwa 5 000 FBu.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-loan-women-group-loan-fr', 'loan_women_group_loan', 'loan_info', 'fr', 'Crédit groupe solidaire de femmes', 'Crédit groupe solidaire de femmes : Pour les groupes de 5 à 20 femmes qui se portent caution mutuelle, sans autre garantie. Taux : 10 % par an. Montant : de 200 000 FBu à 5 000 000 FBu. Durée : de 3 à 24 mois. Conditions : Groupe de 5 à 20 membres avec un compte de groupe; CNI de chaque membre; Procès-verbal de constitution du groupe. Frais de dossier : 1 % du montant, minimum 5 000 FBu.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-loan-women-group-loan-en', 'loan_women_group_loan', 'loan_info', 'en', 'Women''s solidarity group loan', 'Women''s solidarity group loan: For groups of 5 to 20 women who guarantee each other, with no other collateral. Rate: 10% per year. Amount: from 200,000 FBu to 5,000,000 FBu. Term: from 3 to 24 months. Requirements: Group of 5 to 20 members with a group account; National ID of each member; Minutes of the group''s founding meeting. Processing fee: 1% of the amount, minimum 5,000 FBu.');
INSERT INTO kb_articles (id, topic, intent, lang, title, body) VALUES ('kb-loan-women-group-loan-rn', 'loan_women_group_loan', 'loan_info', 'rn', 'Ingurane y''imigwi y''abagore', 'Ingurane y''imigwi y''abagore: Ku migwi y''abagore kuva kuri 5 gushika kuri 20 bishingana, ata yindi ngwati. Inyungu: 10 % ku mwaka. Amafaranga: kuva kuri 200 000 FBu gushika kuri 5 000 000 FBu. Igihe: kuva ku mezi 3 gushika ku mezi 24. Ivyo bisaba: Umugwi w''abantu 5 gushika kuri 20 ufise konti y''umugwi; Karangamuntu ya buri munywanyi; Inyandiko yo gushinga umugwi. Amafaranga y''idosiye: 1 % y''ayo musaba, ntarengwa 5 000 FBu.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-account-opening-individual-fr-0', 'kb-account-opening-individual-fr', 'Ouvrir un compte personnel', 'fr', 0, 'Ouvrir un compte personnel. Pour ouvrir un compte courant ou d''épargne personnel, présentez-vous dans n''importe quelle agence avec : votre carte nationale d''identité (CNI) ou votre passeport en cours de validité, deux photos d''identité récentes et une attestation de résidence délivrée par votre commune. Le dépôt minimum à l''ouverture est de 10 000 FBu pour un compte courant et de 5 000 FBu pour un compte d''épargne. Le compte est ouvert le jour même et la carte de débit est prête en 5 jours ouvrables. Les mineurs ouvrent un compte avec un parent ou tuteur qui présente sa propre CNI et l''acte de naissance de l''enfant.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-account-opening-individual-en-0', 'kb-account-opening-individual-en', 'Opening a personal account', 'en', 0, 'Opening a personal account. To open a personal current or savings account, visit any branch with: your valid national ID card (CNI) or passport, two recent passport photos and a certificate of residence from your commune. The minimum opening deposit is 10,000 FBu for a current account and 5,000 FBu for a savings account. The account is opened the same day and the debit card is ready in 5 working days. Minors open an account with a parent or guardian, who brings their own ID and the child''s birth certificate.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-account-opening-individual-rn-0', 'kb-account-opening-individual-rn', 'Kwugurura konti y''umuntu ku giti ciwe', 'rn', 0, 'Kwugurura konti y''umuntu ku giti ciwe. Kugira mwugurure konti isanzwe canke konti yo kuzigama, nimuze ku ishami iryo ari ryo ryose muzanye: ikarata karangamuntu (CNI) canke pasiporo itararenza igihe, amafoto abiri mashasha n''icemezo c''aho muba gitangwa na komine. Amafaranga make yo gutangura ni 10 000 FBu kuri konti isanzwe na 5 000 FBu kuri konti yo kuzigama. Konti yugururwa uwo musi nyene, ikarata ikaboneka mu misi 5 y''akazi. Abana bato bugururirwa konti n''umuvyeyi canke uwubarera, azana karangamuntu yiwe n''icemezo c''amavuka c''umwana.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-account-opening-business-fr-0', 'kb-account-opening-business-fr', 'Ouvrir un compte entreprise ou association', 'fr', 0, 'Ouvrir un compte entreprise ou association. Pour un compte d''entreprise, apportez : le registre de commerce, le numéro d''identification fiscale (NIF), les statuts de la société, la CNI de chaque signataire et le procès-verbal désignant les signataires. Pour une association ou une coopérative, apportez l''agrément, les statuts et la liste des membres du comité. Le dépôt minimum est de 50 000 FBu. L''ouverture prend 2 jours ouvrables après réception du dossier complet.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-account-opening-business-en-0', 'kb-account-opening-business-en', 'Opening a business or association account', 'en', 0, 'Opening a business or association account. For a business account, bring: the trade register certificate, the tax identification number (NIF), the company statutes, the national ID of each signatory and the minutes naming the signatories. For an association or cooperative, bring the official approval, the statutes and the list of committee members. The minimum deposit is 50,000 FBu. Opening takes 2 working days after the full file is received.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-account-opening-business-rn-0', 'kb-account-opening-business-rn', 'Kwugurura konti y''ishirahamwe canke y''umugwi', 'rn', 0, 'Kwugurura konti y''ishirahamwe canke y''umugwi. Ku konti y''ishirahamwe ry''ubudandaji, muzane: icemezo c''iyandikwa mu bucuruzi, inomero y''umusoro (NIF), amategeko ngenderwako y''ishirahamwe, karangamuntu y''umuntu wese azosinya n''inyandiko ishinga abazosinya. Ku mugwi canke koperative, muzane uruhusha, amategeko ngenderwako n''urutonde rw''abagize komite. Amafaranga make yo gutangura ni 50 000 FBu. Konti yugururwa mu misi 2 y''akazi inyuma yo kwakira impapuro zose.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-account-types-fr-0', 'kb-account-types-fr', 'Nos comptes', 'fr', 0, 'Nos comptes. Compte courant : pour les opérations de tous les jours, carte de débit incluse, frais de tenue de compte de 2 000 FBu par mois. Compte d''épargne : intérêt de 3 % par an, sans frais de tenue, deux retraits gratuits par mois. Compte jeune (moins de 25 ans) : sans frais de tenue de compte, carte de débit gratuite la première année. Tous les comptes donnent accès à la banque mobile et au service *123#.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-account-types-en-0', 'kb-account-types-en', 'Our accounts', 'en', 0, 'Our accounts. Current account: for everyday banking, debit card included, maintenance fee of 2,000 FBu per month. Savings account: 3% interest per year, no maintenance fee, two free withdrawals per month. Youth account (under 25): no maintenance fee, free debit card for the first year. All accounts include mobile banking and the *123# service.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-account-types-rn-0', 'kb-account-types-rn', 'Konti zacu', 'rn', 0, 'Konti zacu. Konti isanzwe: ni iyo gukoresha buri musi, irimwo ikarata, amafaranga yo kuyibungabunga ni 2 000 FBu ku kwezi. Konti yo kuzigama: inyungu ya 3 % ku mwaka, nta mafaranga yo kuyibungabunga, mushobora gukura amafaranga kabiri ku kwezi ata co murihiye. Konti y''urwaruka (munsi y''imyaka 25): nta mafaranga yo kuyibungabunga, ikarata ni ubuntu mu mwaka wa mbere. Konti zose zirashobora gukoreshwa kuri terefone no kuri *123#.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-debit-cards-fr-0', 'kb-debit-cards-fr', 'Cartes de débit', 'fr', 0, 'Cartes de débit. Nous proposons une carte Visa débit, utilisable au Burundi et à l''étranger, et une carte de débit locale, utilisable dans nos guichets automatiques et chez les commerçants partenaires au Burundi. Frais d''émission : 10 000 FBu. Cotisation annuelle : 12 000 FBu pour la Visa, 6 000 FBu pour la carte locale. Retrait gratuit à nos guichets automatiques, 1 000 FBu dans ceux d''autres banques. Plafond de retrait : 1 000 000 FBu par jour.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-debit-cards-en-0', 'kb-debit-cards-en', 'Debit cards', 'en', 0, 'Debit cards. We offer a Visa debit card, usable in Burundi and abroad, and a local debit card, usable at our ATMs and at partner merchants in Burundi. Issuing fee: 10,000 FBu. Annual fee: 12,000 FBu for Visa, 6,000 FBu for the local card. Withdrawals are free at our ATMs and cost 1,000 FBu at other banks'' ATMs. Withdrawal limit: 1,000,000 FBu per day.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-debit-cards-rn-0', 'kb-debit-cards-rn', 'Amakarata yo kubikuza', 'rn', 0, 'Amakarata yo kubikuza. Dufise ikarata Visa ikoreshwa mu Burundi no hanze y''igihugu, n''ikarata y''imbere mu gihugu ikoreshwa ku byuma vyacu vya ATM no ku badandaji dukorana mu Burundi. Amafaranga yo kuyironka: 10 000 FBu. Amafaranga y''umwaka: 12 000 FBu kuri Visa, 6 000 FBu ku karata y''imbere mu gihugu. Gukura amafaranga ku byuma vyacu ni ubuntu, ku vy''izindi banki ni 1 000 FBu. Ntimushobora gukura arenga 1 000 000 FBu ku musi.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-card-lost-stolen-fr-0', 'kb-card-lost-stolen-fr', 'Carte perdue ou volée', 'fr', 0, 'Carte perdue ou volée. Si votre carte est perdue ou volée, faites-la bloquer immédiatement : par ce service d''appel, par le menu *123# (option 2) ou dans une agence. Pour bloquer la carte, nous vérifions votre identité avec votre numéro de compte et votre code PIN ou votre date de naissance. Vous recevez un numéro de référence de blocage. Le blocage est définitif : pour une nouvelle carte, passez en agence avec votre CNI. Le remplacement coûte 10 000 FBu et la carte est prête en 5 jours ouvrables. Ne communiquez jamais votre code PIN par SMS ou WhatsApp.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-card-lost-stolen-en-0', 'kb-card-lost-stolen-en', 'Lost or stolen card', 'en', 0, 'Lost or stolen card. If your card is lost or stolen, have it blocked immediately: through this call service, through the *123# menu (option 2) or at a branch. To block the card we check your identity with your account number and your PIN or date of birth. You receive a block reference number. Blocking is permanent: for a new card, visit a branch with your national ID. Replacement costs 10,000 FBu and the card is ready in 5 working days. Never send your PIN by SMS or WhatsApp.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-card-lost-stolen-rn-0', 'kb-card-lost-stolen-rn', 'Ikarata yatakaye canke yibwe', 'rn', 0, 'Ikarata yatakaye canke yibwe. Ikarata yanyu niyatakara canke ikibwa, nimuyihagarike ubwo nyene: muciye kuri iyi serivisi, kuri *123# (ihitamwo rya 2) canke ku ishami. Kugira duhagarike ikarata, turabanza kwemeza ko ari mwebwe dukoresheje inomero ya konti n''inomero y''ibanga (PIN) canke itariki y''amavuka. Murahabwa inomero y''icemezo c''ihagarikwa. Ikarata ihagaritswe ntisubira gukora: kugira muronke iyindi, nimuze ku ishami muzanye karangamuntu. Iyindi karata ni 10 000 FBu, ikaboneka mu misi 5 y''akazi. Ntimukigere murungika inomero y''ibanga kuri SMS canke WhatsApp.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-card-blocked-pin-fr-0', 'kb-card-blocked-pin-fr', 'Carte bloquée après des codes PIN erronés', 'fr', 0, 'Carte bloquée après des codes PIN erronés. Après 3 codes PIN erronés, la carte se bloque automatiquement pour votre sécurité. Pour la débloquer, passez dans une agence avec votre CNI et votre carte : le déblocage est gratuit et se fait dans les 24 heures. Si vous avez oublié votre code PIN, l''agence vous remet un nouveau code sous pli fermé contre 2 000 FBu. Si la carte a été avalée par un guichet automatique, voir l''article sur les cartes avalées.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-card-blocked-pin-en-0', 'kb-card-blocked-pin-en', 'Card blocked after wrong PIN entries', 'en', 0, 'Card blocked after wrong PIN entries. After 3 wrong PIN entries the card blocks automatically for your safety. To unblock it, visit a branch with your national ID and your card: unblocking is free and done within 24 hours. If you forgot your PIN, the branch gives you a new PIN in a sealed envelope for 2,000 FBu. If an ATM kept the card, see the article on swallowed cards.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-card-blocked-pin-rn-0', 'kb-card-blocked-pin-rn', 'Ikarata yahagaze kubera inomero y''ibanga itari yo', 'rn', 0, 'Ikarata yahagaze kubera inomero y''ibanga itari yo. Iyo mwinjije inomero y''ibanga itari yo incuro 3, ikarata ica ihagarara ubwayo kugira ngo mukingirwe. Kugira yongere ikore, nimuze ku ishami muzanye karangamuntu n''ikarata: ni ubuntu, bikorwa mu masaha 24. Nimwaba mwibagiye inomero y''ibanga, ishami rirabaha iyindi mu ibahasha ifunze ku 2 000 FBu. Nimba icuma ca ATM camize ikarata, raba ingingo ivuga ku makarata yamizwe.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-card-swallowed-atm-fr-0', 'kb-card-swallowed-atm-fr', 'Carte avalée par un guichet automatique', 'fr', 0, 'Carte avalée par un guichet automatique. Si un de nos guichets automatiques a gardé votre carte, elle est remise à l''agence la plus proche du guichet dans un délai de 2 jours ouvrables. Retirez-la en agence avec votre CNI ; c''est gratuit. Si c''est le guichet d''une autre banque, le délai est de 7 jours ouvrables. Si vous pensez que la carte a été volée au guichet, demandez son blocage immédiat.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-card-swallowed-atm-en-0', 'kb-card-swallowed-atm-en', 'Card swallowed by an ATM', 'en', 0, 'Card swallowed by an ATM. If one of our ATMs kept your card, it is sent to the branch nearest that ATM within 2 working days. Collect it at the branch with your national ID; this is free. If it was another bank''s ATM, it takes 7 working days. If you think the card was stolen at the ATM, ask for it to be blocked immediately.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-card-swallowed-atm-rn-0', 'kb-card-swallowed-atm-rn', 'Ikarata yamizwe n''icuma ca ATM', 'rn', 0, 'Ikarata yamizwe n''icuma ca ATM. Nimba icuma cacu ca ATM cagumanye ikarata yanyu, irashikirizwa ishami riri hafi y''ico cuma mu misi 2 y''akazi. Muyitora ku ishami muzanye karangamuntu; ni ubuntu. Nimba ari icuma c''iyindi banki, bifata imisi 7 y''akazi. Nimwiyumvira ko ikarata yibiwe kuri ATM, nimusabe ko ihagarikwa ubwo nyene.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-mobile-banking-fr-0', 'kb-mobile-banking-fr', 'Banque mobile et *123#', 'fr', 0, 'Banque mobile et *123#. Avec l''application mobile ou le menu *123# (fonctionne sur tous les téléphones, sans internet), vous pouvez consulter votre solde, voir vos 5 dernières opérations, bloquer votre carte, poser une question et déposer une réclamation. L''inscription est gratuite en agence ou par ce service d''appel. Chaque consultation de solde par *123# coûte 100 FBu.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-mobile-banking-en-0', 'kb-mobile-banking-en', 'Mobile banking and *123#', 'en', 0, 'Mobile banking and *123#. With the mobile app or the *123# menu (works on every phone, no internet needed), you can check your balance, see your last 5 transactions, block your card, ask a question and file a complaint. Registration is free at a branch or through this call service. Each balance check by *123# costs 100 FBu.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-mobile-banking-rn-0', 'kb-mobile-banking-rn', 'Banki kuri terefone na *123#', 'rn', 0, 'Banki kuri terefone na *123#. Mukoresheje porogarama ya terefone canke *123# (ikora kuri terefone zose, nta internet ikenewe), murashobora kuraba amafaranga ari kuri konti, kuraba ibikorwa 5 biheruka, guhagarika ikarata, kubaza ikibazo no gutanga ikirego. Kwiyandikisha ni ubuntu ku ishami canke kuri iyi serivisi. Kuraba amafaranga kuri *123# ni 100 FBu incuro imwe.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-fees-schedule-fr-0', 'kb-fees-schedule-fr', 'Principaux frais', 'fr', 0, 'Principaux frais. Tenue de compte courant : 2 000 FBu par mois. Compte d''épargne et compte jeune : sans frais de tenue. Émission de carte : 10 000 FBu ; remplacement : 10 000 FBu. Cotisation annuelle carte Visa : 12 000 FBu ; carte locale : 6 000 FBu. Retrait au guichet automatique d''une autre banque : 1 000 FBu. Nouveau code PIN : 2 000 FBu. Relevé de compte imprimé : 1 500 FBu. Consultation de solde par *123# : 100 FBu. Frais de dossier de crédit : 1 % du montant, minimum 5 000 FBu.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-fees-schedule-en-0', 'kb-fees-schedule-en', 'Main fees', 'en', 0, 'Main fees. Current account maintenance: 2,000 FBu per month. Savings and youth accounts: no maintenance fee. Card issuing: 10,000 FBu; replacement: 10,000 FBu. Annual card fee: Visa 12,000 FBu, local card 6,000 FBu. Withdrawal at another bank''s ATM: 1,000 FBu. New PIN: 2,000 FBu. Printed statement: 1,500 FBu. Balance check by *123#: 100 FBu. Loan processing fee: 1% of the amount, minimum 5,000 FBu.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-fees-schedule-rn-0', 'kb-fees-schedule-rn', 'Amafaranga nyamukuru y''ibikorwa', 'rn', 0, 'Amafaranga nyamukuru y''ibikorwa. Kubungabunga konti isanzwe: 2 000 FBu ku kwezi. Konti yo kuzigama na konti y''urwaruka: nta mafaranga yo kuzibungabunga. Kuronka ikarata: 10 000 FBu; kuyisubiza: 10 000 FBu. Amafaranga y''umwaka y''ikarata: Visa 12 000 FBu, ikarata y''imbere mu gihugu 6 000 FBu. Gukura amafaranga ku cuma c''iyindi banki: 1 000 FBu. Inomero y''ibanga nshasha: 2 000 FBu. Urupapuro rw''ibikorwa vya konti: 1 500 FBu. Kuraba amafaranga kuri *123#: 100 FBu. Amafaranga y''idosiye y''ingurane: 1 % y''ayo musaba, ntarengwa 5 000 FBu nk''amake.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-loans-overview-fr-0', 'kb-loans-overview-fr', 'Nos crédits en bref', 'fr', 0, 'Nos crédits en bref. Nous proposons six crédits : crédit commerce, crédit agricole, avance sur salaire, crédit habitat, crédit scolaire et crédit groupe solidaire de femmes. Conditions communes : avoir un compte chez nous, présenter sa CNI, prouver des revenus réguliers et payer les frais de dossier (1 % du montant, minimum 5 000 FBu). La réponse est donnée en 5 jours ouvrables après réception du dossier complet. Ce service peut calculer votre mensualité à partir du montant et de la durée.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-loans-overview-en-0', 'kb-loans-overview-en', 'Our loans at a glance', 'en', 0, 'Our loans at a glance. We offer six loans: business loan, agricultural loan, salary advance, housing loan, school fees loan and women''s solidarity group loan. Common conditions: hold an account with us, show your national ID, prove regular income and pay the processing fee (1% of the amount, minimum 5,000 FBu). You get an answer within 5 working days after the full file is received. This service can calculate your monthly payment from the amount and the term.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-loans-overview-rn-0', 'kb-loans-overview-rn', 'Ingurane zacu muri make', 'rn', 0, 'Ingurane zacu muri make. Dufise ingurane zitandatu: ingurane y''ubudandaji, ingurane y''uburimyi, ingurane y''umushahara, ingurane yo kwubaka inzu, ingurane y''amashure n''ingurane y''imigwi y''abagore. Ivyo zose zisaba: kuba mufise konti iwacu, kwerekana karangamuntu, kwerekana ko mufise amafaranga yinjira buri gihe no kuriha amafaranga y''idosiye (1 % y''ayo musaba, ntarengwa 5 000 FBu). Inyishu itangwa mu misi 5 y''akazi inyuma yo kwakira impapuro zose. Iyi serivisi irashobora kubaharurira ivyo muzoriha buri kwezi mukurikije amafaranga n''igihe.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-complaint-process-fr-0', 'kb-complaint-process-fr', 'Déposer une réclamation', 'fr', 0, 'Déposer une réclamation. Vous pouvez déposer une réclamation par ce service d''appel, par *123# (option 4), par WhatsApp ou en agence. Chaque réclamation reçoit un numéro de ticket (par exemple TCK-2026-00042) à conserver. Nous confirmons la réception dans les 24 heures et visons une réponse en 5 jours ouvrables. Si des frais ont été prélevés par erreur, ils sont remboursés dans les 5 jours ouvrables après vérification. Une réclamation urgente (fraude, argent manquant) est transmise immédiatement à un conseiller.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-complaint-process-en-0', 'kb-complaint-process-en', 'Filing a complaint', 'en', 0, 'Filing a complaint. You can file a complaint through this call service, through *123# (option 4), on WhatsApp or at a branch. Each complaint gets a ticket number (for example TCK-2026-00042); keep it. We confirm receipt within 24 hours and aim to answer within 5 working days. Fees charged by mistake are refunded within 5 working days after verification. An urgent complaint (fraud, missing money) is passed to an agent immediately.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-complaint-process-rn-0', 'kb-complaint-process-rn', 'Gutanga ikirego', 'rn', 0, 'Gutanga ikirego. Murashobora gutanga ikirego muciye kuri iyi serivisi, kuri *123# (ihitamwo rya 4), kuri WhatsApp canke ku ishami. Ikirego cose gihabwa inomero y''itike (nk''akarorero TCK-2026-00042); muyibike. Turemeza ko twakiriye ikirego mu masaha 24, tukagerageza kwishura mu misi 5 y''akazi. Amafaranga yakuweko ku makosa asubizwa mu misi 5 y''akazi inyuma yo kugenzura. Ikirego cihutirwa (ubusuma, amafaranga yabuze) gishikirizwa umukozi ubwo nyene.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-branch-hours-general-fr-0', 'kb-branch-hours-general-fr', 'Horaires des agences et du service client', 'fr', 0, 'Horaires des agences et du service client. La plupart des agences sont ouvertes du lundi au vendredi de 8 h à 17 h et le samedi de 8 h à 12 h ; elles sont fermées le dimanche et les jours fériés. Les horaires exacts de chaque agence sont donnés par province ou par ville. L''assistant Kabangutsi répond 24 h sur 24. Les conseillers humains répondent du lundi au vendredi de 7 h 30 à 18 h et le samedi de 8 h à 12 h.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-branch-hours-general-en-0', 'kb-branch-hours-general-en', 'Branch and customer service hours', 'en', 0, 'Branch and customer service hours. Most branches are open Monday to Friday from 8:00 to 17:00 and Saturday from 8:00 to 12:00; they are closed on Sundays and public holidays. Exact hours for each branch are given by province or town. The Kabangutsi assistant answers 24 hours a day. Human agents answer Monday to Friday from 7:30 to 18:00 and Saturday from 8:00 to 12:00.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-branch-hours-general-rn-0', 'kb-branch-hours-general-rn', 'Amasaha y''amashami n''aya serivisi y''abakiriya', 'rn', 0, 'Amasaha y''amashami n''aya serivisi y''abakiriya. Amashami menshi akora kuva ku wa mbere gushika ku wa gatanu kuva 8:00 gushika 17:00, no ku wa gatandatu kuva 8:00 gushika 12:00; ntakora ku w''iyinga no ku misi mikuru. Amasaha nyayo ya buri shami atangwa hakurikijwe intara canke igisagara. Umufasha Kabangutsi yishura amasaha 24 kuri 24. Abakozi bishura kuva ku wa mbere gushika ku wa gatanu kuva 7:30 gushika 18:00, no ku wa gatandatu kuva 8:00 gushika 12:00.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-talk-to-agent-fr-0', 'kb-talk-to-agent-fr', 'Parler à un conseiller', 'fr', 0, 'Parler à un conseiller. Dites « je veux parler à un conseiller » à tout moment, ou tapez 0 dans le menu *123#. Votre appel est transféré avec un résumé de la conversation, vous n''avez donc pas à tout répéter. En dehors des heures des conseillers, une réclamation est créée et un conseiller vous rappelle le jour ouvrable suivant.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-talk-to-agent-en-0', 'kb-talk-to-agent-en', 'Talking to an agent', 'en', 0, 'Talking to an agent. Say "I want to talk to an agent" at any time, or press 0 in the *123# menu. Your call is transferred with a summary of the conversation, so you don''t have to repeat everything. Outside agent hours, a ticket is created and an agent calls you back on the next working day.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-talk-to-agent-rn-0', 'kb-talk-to-agent-rn', 'Kuvugana n''umukozi', 'rn', 0, 'Kuvugana n''umukozi. Igihe ico ari co cose, muvuge ngo « ndashaka kuvugana n''umukozi », canke mukande 0 kuri *123#. Umuhamagaro wanyu urashikirizwa umukozi hamwe n''incamake y''ico mwavuganye, ku buryo mutasubiramwo vyose. Inyuma y''amasaha y''abakozi, ikirego kirandikwa, umukozi akabahamagara ku musi w''akazi ukurikira.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-security-tips-fr-0', 'kb-security-tips-fr', 'Conseils de sécurité', 'fr', 0, 'Conseils de sécurité. La banque ne vous demandera jamais votre code PIN par SMS, WhatsApp ou e-mail. Saisissez votre code uniquement sur un guichet automatique, un terminal de paiement ou lors de la vérification d''identité de ce service d''appel. Ne prêtez jamais votre carte. En cas de doute sur un message ou un appel, bloquez votre carte et contactez une agence.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-security-tips-en-0', 'kb-security-tips-en', 'Security tips', 'en', 0, 'Security tips. The bank will never ask for your PIN by SMS, WhatsApp or email. Enter your PIN only at an ATM, a payment terminal or during the identity check of this call service. Never lend your card. If a message or a call looks suspicious, block your card and contact a branch.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-security-tips-rn-0', 'kb-security-tips-rn', 'Inama z''umutekano', 'rn', 0, 'Inama z''umutekano. Banki ntizigera ibasaba inomero y''ibanga kuri SMS, WhatsApp canke imeyili. Inomero y''ibanga muyinjiza gusa ku cuma ca ATM, ku cuma co kurihirako canke igihe iyi serivisi ibemeza. Ntimukigere mutiza abandi ikarata yanyu. Nimwakeka ubutumwa canke umuhamagaro, nimuhagarike ikarata mubaze ishami.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-loan-business-loan-fr-0', 'kb-loan-business-loan-fr', 'Crédit commerce', 'fr', 0, 'Crédit commerce. Crédit commerce : Pour financer le stock, l''équipement ou le fonds de roulement d''un commerce. Taux : 16 % par an. Montant : de 500 000 FBu à 50 000 000 FBu. Durée : de 3 à 36 mois. Conditions : Compte courant chez nous depuis au moins 6 mois; Registre de commerce et NIF; Relevés de compte des 6 derniers mois; Garantie (matériel, stock ou caution) au-delà de 10 000 000 FBu. Frais de dossier : 1 % du montant, minimum 5 000 FBu.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-loan-business-loan-en-0', 'kb-loan-business-loan-en', 'Business loan', 'en', 0, 'Business loan. Business loan: To finance stock, equipment or working capital for a business. Rate: 16% per year. Amount: from 500,000 FBu to 50,000,000 FBu. Term: from 3 to 36 months. Requirements: Current account with us for at least 6 months; Trade register certificate and NIF; Account statements for the last 6 months; Collateral (equipment, stock or guarantor) above 10,000,000 FBu. Processing fee: 1% of the amount, minimum 5,000 FBu.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-loan-business-loan-rn-0', 'kb-loan-business-loan-rn', 'Ingurane y''ubudandaji', 'rn', 0, 'Ingurane y''ubudandaji. Ingurane y''ubudandaji: Ifasha kugura ibidandazwa, ibikoresho canke amafaranga yo gukoresha mu budandaji. Inyungu: 16 % ku mwaka. Amafaranga: kuva kuri 500 000 FBu gushika kuri 50 000 000 FBu. Igihe: kuva ku mezi 3 gushika ku mezi 36. Ivyo bisaba: Konti isanzwe iwacu imaze nibura amezi 6; Icemezo c''iyandikwa mu bucuruzi na NIF; Impapuro z''ibikorwa vya konti z''amezi 6 aheruka; Ingwati (ibikoresho, ibidandazwa canke umwishingizi) iyo ingurane irenze 10 000 000 FBu. Amafaranga y''idosiye: 1 % y''ayo musaba, ntarengwa 5 000 FBu.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-loan-agri-loan-fr-0', 'kb-loan-agri-loan-fr', 'Crédit agricole', 'fr', 0, 'Crédit agricole. Crédit agricole : Pour les producteurs de café, de thé et de cultures vivrières : intrants, main-d''œuvre, petit matériel. Remboursement possible en une fois après la récolte. Taux : 12 % par an. Montant : de 100 000 FBu à 10 000 000 FBu. Durée : de 3 à 18 mois. Conditions : Compte chez nous; Attestation de la coopérative ou de la station de lavage; Reçus de livraison de la dernière récolte. Frais de dossier : 1 % du montant, minimum 5 000 FBu.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-loan-agri-loan-en-0', 'kb-loan-agri-loan-en', 'Agricultural loan', 'en', 0, 'Agricultural loan. Agricultural loan: For coffee, tea and food crop farmers: inputs, labour, small equipment. Can be repaid in one payment after the harvest. Rate: 12% per year. Amount: from 100,000 FBu to 10,000,000 FBu. Term: from 3 to 18 months. Requirements: Account with us; Certificate from the cooperative or washing station; Delivery receipts from the last harvest. Processing fee: 1% of the amount, minimum 5,000 FBu.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-loan-agri-loan-rn-0', 'kb-loan-agri-loan-rn', 'Ingurane y''uburimyi', 'rn', 0, 'Ingurane y''uburimyi. Ingurane y''uburimyi: Ku barimyi b''ikawa, icayi n''ibifungurwa: ifumbire, imbuto, abakozi, ibikoresho bito. Irashobora kurihwa rimwe inyuma y''isarura. Inyungu: 12 % ku mwaka. Amafaranga: kuva kuri 100 000 FBu gushika kuri 10 000 000 FBu. Igihe: kuva ku mezi 3 gushika ku mezi 18. Ivyo bisaba: Konti iwacu; Icemezo ca koperative canke c''aho bogereza ikawa; Ivyemezo vyo gutanga umwimbu uheruka. Amafaranga y''idosiye: 1 % y''ayo musaba, ntarengwa 5 000 FBu.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-loan-salary-advance-fr-0', 'kb-loan-salary-advance-fr', 'Avance sur salaire', 'fr', 0, 'Avance sur salaire. Avance sur salaire : Pour les salariés dont le salaire est versé chez nous : jusqu''à 50 % du salaire net mensuel par mois de remboursement. Taux : 14 % par an. Montant : de 50 000 FBu à 5 000 000 FBu. Durée : de 1 à 24 mois. Conditions : Salaire domicilié chez nous depuis 3 mois; Attestation de service de l''employeur; Trois derniers bulletins de paie. Frais de dossier : 1 % du montant, minimum 5 000 FBu.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-loan-salary-advance-en-0', 'kb-loan-salary-advance-en', 'Salary advance', 'en', 0, 'Salary advance. Salary advance: For employees whose salary is paid into an account with us: monthly repayments of up to 50% of net monthly salary. Rate: 14% per year. Amount: from 50,000 FBu to 5,000,000 FBu. Term: from 1 to 24 months. Requirements: Salary paid into an account with us for 3 months; Employment certificate from the employer; Last three payslips. Processing fee: 1% of the amount, minimum 5,000 FBu.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-loan-salary-advance-rn-0', 'kb-loan-salary-advance-rn', 'Ingurane y''umushahara', 'rn', 0, 'Ingurane y''umushahara. Ingurane y''umushahara: Ku bakozi bahemberwa kuri konti iwacu: ico muriha buri kwezi ntigishobora kurenza 50 % y''umushahara. Inyungu: 14 % ku mwaka. Amafaranga: kuva kuri 50 000 FBu gushika kuri 5 000 000 FBu. Igihe: kuva ku mezi 1 gushika ku mezi 24. Ivyo bisaba: Umushahara uca iwacu mu mezi 3 aheruka; Icemezo c''akazi gitangwa n''umukoresha; Impapuro z''umushahara z''amezi 3 aheruka. Amafaranga y''idosiye: 1 % y''ayo musaba, ntarengwa 5 000 FBu.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-loan-housing-loan-fr-0', 'kb-loan-housing-loan-fr', 'Crédit habitat', 'fr', 0, 'Crédit habitat. Crédit habitat : Pour construire, acheter ou rénover un logement. Taux : 15 % par an. Montant : de 5 000 000 FBu à 150 000 000 FBu. Durée : de 12 à 180 mois. Conditions : Revenus réguliers prouvés; Titre de propriété ou certificat d''enregistrement de la parcelle; Devis ou plan de construction; Apport personnel d''au moins 20 %. Frais de dossier : 1 % du montant, minimum 5 000 FBu.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-loan-housing-loan-en-0', 'kb-loan-housing-loan-en', 'Housing loan', 'en', 0, 'Housing loan. Housing loan: To build, buy or renovate a home. Rate: 15% per year. Amount: from 5,000,000 FBu to 150,000,000 FBu. Term: from 12 to 180 months. Requirements: Proof of regular income; Land title or plot registration certificate; Construction quote or plan; Own contribution of at least 20%. Processing fee: 1% of the amount, minimum 5,000 FBu.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-loan-housing-loan-rn-0', 'kb-loan-housing-loan-rn', 'Ingurane yo kwubaka', 'rn', 0, 'Ingurane yo kwubaka. Ingurane yo kwubaka: Ifasha kwubaka, kugura canke gusubiramwo inzu. Inyungu: 15 % ku mwaka. Amafaranga: kuva kuri 5 000 000 FBu gushika kuri 150 000 000 FBu. Igihe: kuva ku mezi 12 gushika ku mezi 180. Ivyo bisaba: Kwerekana amafaranga yinjira buri gihe; Icemezo c''itongo; Igiciro canke igishushanyo c''inzu; Gutanga nibura 20 % y''amafaranga yose. Amafaranga y''idosiye: 1 % y''ayo musaba, ntarengwa 5 000 FBu.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-loan-school-fees-loan-fr-0', 'kb-loan-school-fees-loan-fr', 'Crédit scolaire', 'fr', 0, 'Crédit scolaire. Crédit scolaire : Pour payer les frais scolaires et universitaires au début de l''année ou du trimestre. Taux : 13 % par an. Montant : de 100 000 FBu à 3 000 000 FBu. Durée : de 3 à 10 mois. Conditions : Compte chez nous; Facture ou attestation d''inscription de l''école; Preuve de revenus. Frais de dossier : 1 % du montant, minimum 5 000 FBu.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-loan-school-fees-loan-en-0', 'kb-loan-school-fees-loan-en', 'School fees loan', 'en', 0, 'School fees loan. School fees loan: To pay school or university fees at the start of the year or term. Rate: 13% per year. Amount: from 100,000 FBu to 3,000,000 FBu. Term: from 3 to 10 months. Requirements: Account with us; School invoice or enrolment certificate; Proof of income. Processing fee: 1% of the amount, minimum 5,000 FBu.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-loan-school-fees-loan-rn-0', 'kb-loan-school-fees-loan-rn', 'Ingurane y''amashure', 'rn', 0, 'Ingurane y''amashure. Ingurane y''amashure: Ifasha kuriha amafaranga y''ishure canke kaminuza mu ntango y''umwaka canke y''igihembwe. Inyungu: 13 % ku mwaka. Amafaranga: kuva kuri 100 000 FBu gushika kuri 3 000 000 FBu. Igihe: kuva ku mezi 3 gushika ku mezi 10. Ivyo bisaba: Konti iwacu; Inyemezamafaranga canke icemezo c''ishure; Kwerekana amafaranga yinjira. Amafaranga y''idosiye: 1 % y''ayo musaba, ntarengwa 5 000 FBu.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-loan-women-group-loan-fr-0', 'kb-loan-women-group-loan-fr', 'Crédit groupe solidaire de femmes', 'fr', 0, 'Crédit groupe solidaire de femmes. Crédit groupe solidaire de femmes : Pour les groupes de 5 à 20 femmes qui se portent caution mutuelle, sans autre garantie. Taux : 10 % par an. Montant : de 200 000 FBu à 5 000 000 FBu. Durée : de 3 à 24 mois. Conditions : Groupe de 5 à 20 membres avec un compte de groupe; CNI de chaque membre; Procès-verbal de constitution du groupe. Frais de dossier : 1 % du montant, minimum 5 000 FBu.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-loan-women-group-loan-en-0', 'kb-loan-women-group-loan-en', 'Women''s solidarity group loan', 'en', 0, 'Women''s solidarity group loan. Women''s solidarity group loan: For groups of 5 to 20 women who guarantee each other, with no other collateral. Rate: 10% per year. Amount: from 200,000 FBu to 5,000,000 FBu. Term: from 3 to 24 months. Requirements: Group of 5 to 20 members with a group account; National ID of each member; Minutes of the group''s founding meeting. Processing fee: 1% of the amount, minimum 5,000 FBu.');
INSERT INTO kb_chunks (id, article_id, source, lang, chunk_index, text) VALUES ('kb-loan-women-group-loan-rn-0', 'kb-loan-women-group-loan-rn', 'Ingurane y''imigwi y''abagore', 'rn', 0, 'Ingurane y''imigwi y''abagore. Ingurane y''imigwi y''abagore: Ku migwi y''abagore kuva kuri 5 gushika kuri 20 bishingana, ata yindi ngwati. Inyungu: 10 % ku mwaka. Amafaranga: kuva kuri 200 000 FBu gushika kuri 5 000 000 FBu. Igihe: kuva ku mezi 3 gushika ku mezi 24. Ivyo bisaba: Umugwi w''abantu 5 gushika kuri 20 ufise konti y''umugwi; Karangamuntu ya buri munywanyi; Inyandiko yo gushinga umugwi. Amafaranga y''idosiye: 1 % y''ayo musaba, ntarengwa 5 000 FBu.');
